1	import { randomUUID } from 'node:crypto';
2	import { db } from './db';
3	import { completeJSON, provider } from './llm';
4	import { ensureSchema } from './schema';
5	import {
6	  HARD_CAP, MAX_QUESTIONS, RECOMMEND, TRACKS, CLEAR, QUESTION_SYSTEM, CONCEPT_SYSTEM,
7	  applyAnswer, blockedTrack, conceptUser, decisions, goalLine, initialLedger, label, mockConcept, mockQuestion,
8	  overall, parseConcept, parseQuestion, pickTrack, questionUser, shouldStop,
9	  type Answer, type Ledger, type Question, type TrackKey, type Turn,
10	} from './interview';
11	
12	type TurnRow = { id: string; idx: number; track: TrackKey; question: string; hint: string | null; options: string; allow_free: number; multi: number; answer: string | null; ledger: string | null; provider: string | null };
13	type SessionRow = { id: string; prompt: string; status: 'interviewing' | 'done'; ambiguity: number | null; tracks: string | null; created_at: string };
14	
15	export type TurnView = { id: string; idx: number; track: TrackKey; trackLabel: string; question: string; hint: string; options: string[]; multi: boolean; allowFree: boolean; answer: Answer | null; provider: string };
16	export type Concept = { what: string; analogy: string; details: string[]; so_what: string; decisions: { track: string; decision: string }[] };
17	export type State = {
18	  id: string; prompt: string; status: 'interviewing' | 'done'; createdAt: string;
19	  overall: number; ledger: { key: TrackKey; label: string; score: number; clear: boolean }[];
20	  turns: TurnView[]; open: TurnView | null;
21	  restate: { goal: string; decisions: { track: string; decision: string }[]; fuzzy: string[]; canAskMore: boolean } | null;
22	  result: { title: string; one_liner: string; concept: Concept; provider: string } | null;
23	  maxQuestions: number;
24	};
25	
26	const now = () => new Date().toISOString();
27	const newId = () => randomUUID().replaceAll('-', '').slice(0, 10);
28	
29	function rows(id: string) {
30	  ensureSchema();
31	  const s = db().prepare('SELECT * FROM step1_sessions WHERE id = ?').get(id) as SessionRow | undefined;
32	  if (!s) return null;
33	  const t = db().prepare('SELECT * FROM step1_turns WHERE session_id = ? ORDER BY idx').all(id) as TurnRow[];
34	  return { s, t, ledger: JSON.parse(s.tracks ?? '{}') as Ledger };
35	}
36	
37	const toTurn = (r: TurnRow): Turn => ({ track: r.track, question: r.question, options: JSON.parse(r.options), answer: r.answer ? JSON.parse(r.answer) : null });
38	
39	export function getState(id: string): State | null {
40	  const x = rows(id);
41	  if (!x) return null;
42	  const { s, t, ledger } = x;
43	  const views: TurnView[] = t.map((r) => ({
44	    id: r.id, idx: r.idx, track: r.track, trackLabel: label(r.track), question: r.question, hint: r.hint ?? '',
45	    options: JSON.parse(r.options), multi: !!r.multi, allowFree: !!r.allow_free, answer: r.answer ? JSON.parse(r.answer) : null, provider: r.provider ?? '',
46	  }));
47	  const open = views.find((v) => !v.answer) ?? null;
48	  const turns = t.map(toTurn);
49	  const res = db().prepare('SELECT * FROM step1_results WHERE session_id = ?').get(id) as { title: string; one_liner: string; concept: string; provider: string | null } | undefined;
50	  const ledgerView = TRACKS.map((tr) => ({ key: tr.key, label: tr.label, score: ledger[tr.key] ?? 1, clear: (ledger[tr.key] ?? 1) <= CLEAR }));
51	  return {
52	    id: s.id, prompt: s.prompt, status: s.status, createdAt: s.created_at,
53	    overall: overall(ledger), ledger: ledgerView, turns: views, open,
54	    restate: s.status === 'interviewing' && !open
55	      ? { goal: goalLine(s.prompt, turns), decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })), fuzzy: ledgerView.filter((l) => !l.clear).map((l) => l.label), canAskMore: t.length < HARD_CAP }
56	      : null,
57	    result: res ? { title: res.title, one_liner: res.one_liner, concept: JSON.parse(res.concept), provider: res.provider ?? '' } : null,
58	    maxQuestions: MAX_QUESTIONS,
59	  };
60	}
61	
62	export function listSessions(limit = 20) {
63	  ensureSchema();
64	  return db().prepare(`
65	    SELECT s.id, s.prompt, s.status, s.created_at, r.title, (SELECT COUNT(*) FROM step1_turns t WHERE t.session_id = s.id AND t.answer IS NOT NULL) AS answered
66	    FROM step1_sessions s LEFT JOIN step1_results r ON r.session_id = s.id ORDER BY s.created_at DESC LIMIT ?`).all(limit) as
67	    { id: string; prompt: string; status: string; created_at: string; title: string | null; answered: number }[];
68	}
69	
70	/** Ask the next question (LLM, or the mock bank when the model is off/fails/breaks a rule). No-op if one is already open. */
71	async function askNext(id: string, force = false): Promise<void> {
72	  const x = rows(id)!;
73	  if (x.t.some((r) => !r.answer) || x.s.status !== 'interviewing') return;
74	  const turns = x.t.map(toTurn);
75	  if (turns.length >= HARD_CAP || (!force && shouldStop(x.ledger, turns.length))) return;
76	  const history = turns.map((t) => t.track);
77	  const blocked = blockedTrack(history);
78	  const target = pickTrack(x.ledger, history);
79	  const mock = () => ({ ...mockQuestion(x.s.prompt, turns, target), ambiguity: x.ledger, done: false });
80	  const res = await completeJSON(QUESTION_SYSTEM, questionUser(x.s.prompt, turns, x.ledger, target, blocked), mock);
81	  const parsed = parseQuestion(res.data, blocked);
82	  const ledger = { ...x.ledger, ...parsed.ledger };
83	  let q: Question;
84	  let used: string = res.provider;
85	  if (parsed.q) q = parsed.q;
86	  else if (parsed.done && !force && res.provider !== 'mock') {
87	    db().prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
88	    return; // model says every track is clear: go to the Restate gate
89	  } else {
90	    const pick = pickTrack(ledger, history);
91	    q = mockQuestion(x.s.prompt, turns, pick);
92	    used = res.provider === 'mock' ? 'mock' : 'mock (LLM 응답을 쓸 수 없어 기본 질문)';
93	  }
94	  if (res.error) used = 'mock (LLM 호출 실패)';
95	  const d = db();
96	  if (d.prepare('SELECT 1 FROM step1_turns WHERE session_id = ? AND answer IS NULL').get(id)) return; // a parallel request won
97	  d.prepare('INSERT INTO step1_turns (id, session_id, idx, track, question, hint, options, allow_free, multi, answer, ledger, provider, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)')
98	    .run(newId(), id, turns.length, q.track, q.question, q.hint, JSON.stringify(q.options), q.allow_free ? 1 : 0, q.multi ? 1 : 0, JSON.stringify(ledger), used, now());
99	  d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
100	}
101	
102	export async function createSession(prompt: string): Promise<string> {
103	  ensureSchema();
104	  const id = newId();
105	  const ledger = initialLedger(prompt);
106	  db().prepare('INSERT INTO step1_sessions (id, prompt, status, ambiguity, tracks, created_at) VALUES (?, ?, ?, ?, ?, ?)').run(id, prompt, 'interviewing', overall(ledger), JSON.stringify(ledger), now());
107	  await askNext(id);
108	  return id;
109	}
110	
111	export class InputError extends Error {}
112	
113	export async function act(id: string, body: Record<string, unknown>): Promise<State | null> {
114	  const x = rows(id);
115	  if (!x) return null;
116	  const open = x.t.find((r) => !r.answer);
117	  const d = db();
118	  switch (body.action) {
119	    case 'answer': {
120	      if (x.s.status !== 'interviewing' || !open || body.turnId !== open.id) throw new InputError('이미 답한 질문이에요. 화면을 새로 고쳐 주세요.');
121	      const options: string[] = JSON.parse(open.options);
122	      const raw = Array.isArray(body.choices) ? body.choices : [];
123	      const choices = [...new Set(raw.filter((c): c is string => typeof c === 'string'))];
124	      if (choices.some((c) => c !== RECOMMEND && !options.includes(c))) throw new InputError('보기에 없는 답이 섞여 있어요.');
125	      if (!open.multi && choices.length > 1) throw new InputError('이 질문은 하나만 고를 수 있어요.');
126	      if (choices.includes(RECOMMEND) && choices.length > 1) throw new InputError('‘추천해 줘’는 다른 보기와 함께 고를 수 없어요.');
127	      const text = typeof body.text === 'string' ? body.text.trim() : '';
128	      if (text.length > 500) throw new InputError('직접 쓰기는 500자까지예요.');
129	      if (!open.allow_free && text) throw new InputError('이 질문은 직접 쓰기를 받지 않아요.');
130	      if (!choices.length && !text) throw new InputError('보기를 고르거나 직접 써 주세요.');
131	      const answer: Answer = { choices, text };
132	      const ledger = applyAnswer(x.ledger, open.track, answer);
133	      d.prepare('UPDATE step1_turns SET answer = ? WHERE id = ?').run(JSON.stringify(answer), open.id);
134	      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
135	      await askNext(id);
136	      break;
137	    }
138	    case 'wrap': // 여기까지로 정리하기: drop the open question, go to the Restate gate
139	      if (x.s.status !== 'interviewing') break;
140	      if (!x.t.some((r) => r.answer)) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
141	      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
142	      break;
143	    case 'more': // Restate gate: "질문 하나 더"
144	      if (x.s.status === 'interviewing' && !open) await askNext(id, true);
145	      break;
146	    case 'back': { // 이전: drop the open question, reopen the last answered one and restore its ledger
147	      if (x.s.status !== 'interviewing') break;
148	      const last = [...x.t].reverse().find((r) => r.answer);
149	      if (!last) break;
150	      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
151	      d.prepare('UPDATE step1_turns SET answer = NULL WHERE id = ?').run(last.id);
152	      const ledger = last.ledger ?? x.s.tracks ?? '{}';
153	      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(ledger, overall(JSON.parse(ledger)), id);
154	      break;
155	    }
156	    case 'finish': { // Restate gate confirmed: write the ELI5 concept
157	      if (x.s.status !== 'interviewing' || open) throw new InputError('정리할 준비가 아직 안 됐어요.');
158	      const turns = x.t.map(toTurn);
159	      if (!turns.length) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
160	      const fallback = mockConcept(x.s.prompt, turns);
161	      const res = await completeJSON(CONCEPT_SYSTEM, conceptUser(x.s.prompt, turns), () => fallback);
162	      const c = parseConcept(res.data, fallback);
163	      const concept = { what: c.what, analogy: c.analogy, details: c.details, so_what: c.so_what, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) };
164	      if (rows(id)!.s.status === 'done') break; // a parallel request already finished it
165	      d.prepare('INSERT OR REPLACE INTO step1_results (session_id, title, one_liner, concept, provider, created_at) VALUES (?, ?, ?, ?, ?, ?)')
166	        .run(id, c.title, c.one_liner, JSON.stringify(concept), res.error ? 'mock (LLM 호출 실패)' : res.provider, now());
167	      d.prepare("UPDATE step1_sessions SET status = 'done' WHERE id = ?").run(id);
168	      break;
169	    }
170	    default:
171	      throw new InputError('알 수 없는 요청이에요.');
172	  }
173	  return getState(id);
174	}
175	
176	export { provider };
