433	export const CONCEPT_SYSTEM = `You turn a finished game-idea interview into a short ELI5 concept card in Korean.
434	${ELI5_RULES}
435	Structure (ELI5): start with the "what" in one sentence, then an analogy, then details, then the "so what".
436	Reply with JSON only:
437	{"title":"게임 이름(가제), 2-12 Korean chars, catchy but plain","one_liner":"one sentence","what":"이게 뭐냐면: one sentence","analogy":"비유하자면: 1-2 sentences","details":["3-6 short bullets"],"so_what":"그래서 왜 재밌냐면: 1-2 sentences"}
438	Do not start values with the section names ("이게 뭐냐면:", "비유하자면:" ...); the app shows them as headings.
439	Use only what the prompt and answers say; do not invent features, numbers or facts.`;
440	
441	export function conceptUser(prompt: string, turns: Turn[]): string {
442	  return JSON.stringify({ prompt, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) });
443	}
