111	export class InputError extends Error {}
112	
113	export async function act(id: string, body: Record<string, unknown>): Promise<State | null> {
114	  const x = rows(id);
115	  if (!x) return null;
116	  const open = x.t.find((r) => !r.answer);
117	  const d = db();
118	  switch (body.action) {
119	    case 'answer': {
120	      if (x.s.status !== 'interviewing' || !open || body.turnId !== open.id) throw new InputError('이미 답한 질문이에요. 화면을 새로 고쳐 주세요.');
121	      const options: string[] = JSON.parse(open.options);
122	      const raw = Array.isArray(body.choices) ? body.choices : [];
123	      const choices = [...new Set(raw.filter((c): c is string => typeof c === 'string'))];
124	      if (choices.some((c) => c !== RECOMMEND && !options.includes(c))) throw new InputError('보기에 없는 답이 섞여 있어요.');
125	      if (!open.multi && choices.length > 1) throw new InputError('이 질문은 하나만 고를 수 있어요.');
126	      if (choices.includes(RECOMMEND) && choices.length > 1) throw new InputError('‘추천해 줘’는 다른 보기와 함께 고를 수 없어요.');
127	      const text = typeof body.text === 'string' ? body.text.trim() : '';
128	      if (text.length > 500) throw new InputError('직접 쓰기는 500자까지예요.');
129	      if (!open.allow_free && text) throw new InputError('이 질문은 직접 쓰기를 받지 않아요.');
130	      if (!choices.length && !text) throw new InputError('보기를 고르거나 직접 써 주세요.');
131	      const answer: Answer = { choices, text };
132	      const ledger = applyAnswer(x.ledger, open.track, answer);
133	      d.prepare('UPDATE step1_turns SET answer = ? WHERE id = ?').run(JSON.stringify(answer), open.id);
134	      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
135	      await askNext(id);
136	      break;
137	    }
138	    case 'wrap': // 여기까지로 정리하기: drop the open question, go to the Restate gate
139	      if (x.s.status !== 'interviewing') break;
140	      if (!x.t.some((r) => r.answer)) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
141	      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
142	      break;
143	    case 'more': // Restate gate: "질문 하나 더"
144	      if (x.s.status === 'interviewing' && !open) await askNext(id, true);
145	      break;
146	    case 'back': { // 이전: drop the open question, reopen the last answered one and restore its ledger
147	      if (x.s.status !== 'interviewing') break;
148	      const last = [...x.t].reverse().find((r) => r.answer);
149	      if (!last) break;
150	      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
151	      d.prepare('UPDATE step1_turns SET answer = NULL WHERE id = ?').run(last.id);
152	      const ledger = last.ledger ?? x.s.tracks ?? '{}';
153	      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(ledger, overall(JSON.parse(ledger)), id);
154	      break;
155	    }
156	    case 'finish': { // Restate gate confirmed: write the ELI5 concept
157	      if (x.s.status !== 'interviewing' || open) throw new InputError('정리할 준비가 아직 안 됐어요.');
158	      const turns = x.t.map(toTurn);
159	      if (!turns.length) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
160	      const fallback = mockConcept(x.s.prompt, turns);
161	      const res = await completeJSON(CONCEPT_SYSTEM, conceptUser(x.s.prompt, turns), () => fallback);
162	      const c = parseConcept(res.data, fallback);
163	      const concept = { what: c.what, analogy: c.analogy, details: c.details, so_what: c.so_what, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) };
164	      if (rows(id)!.s.status === 'done') break; // a parallel request already finished it
165	      d.prepare('INSERT OR REPLACE INTO step1_results (session_id, title, one_liner, concept, provider, created_at) VALUES (?, ?, ?, ?, ?, ?)')
166	        .run(id, c.title, c.one_liner, JSON.stringify(concept), res.error ? 'mock (LLM 호출 실패)' : res.provider, now());
167	      d.prepare("UPDATE step1_sessions SET status = 'done' WHERE id = ?").run(id);
168	      break;
169	    }
170	    default:
171	      throw new InputError('알 수 없는 요청이에요.');
172	  }
173	  return getState(id);
174	}
