  for (const pick of [(q) => ({ choices: [q.options[0]], text: '' }), () => ({ choices: [RECOMMEND], text: '' })]) {
    const qs = run(PROMPT, pick).map((t) => t.question);
    assert.equal(new Set(qs).size, qs.length, qs.join('\n'));
