  const rec = n === 1;
  s = await post({ action: 'answer', turnId: s.open.id, choices: [rec ? '잘 모르겠어요, 추천해 줘' : s.open.options[0]], text: '' });
  n++;
}
console.log('tracks', s.turns.map((t) => t.track).join(','), 'overall', s.overall);
