const b = await post({ action: 'back' });
console.log('after back open', b.open?.idx, 'answer null', b.open?.answer);
s = await post({ action: 'answer', turnId: b.open.id, choices: [b.open.options[0]], text: '다시 답함' });
s = await post({ action: 'finish' });
console.log('status', s.status, 'title', s.result.title, '|', s.result.one_liner, '|', s.result.concept.what);
console.log('decisions', JSON.stringify(s.result.concept.decisions));
EOF
